css:
.mo2-eq-curve{--mo2-eq-curve-accent:#5fe3c9;--mo2-eq-curve-ink:#e9eef8;position:relative;box-sizing:border-box;width:100%;max-width:320px;height:150px;padding:9px 11px 6px;border-radius:14px;background:radial-gradient(130% 110% at 50% -10%,#1a2231 0%,#0e131c 58%,#0b0f16 100%);border:1px solid rgba(255,255,255,.08);box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 14px 28px -18px #000;color:var(--mo2-eq-curve-ink);font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;overflow:hidden;-webkit-user-select:none;user-select:none}
.mo2-eq-curve-top{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.mo2-eq-curve-label{font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:rgba(233,238,248,.42)}
.mo2-eq-curve-value{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:10px;letter-spacing:.04em;color:var(--mo2-eq-curve-accent);text-transform:uppercase;white-space:nowrap}
.mo2-eq-curve-stage{position:relative;height:106px;margin-top:5px}
.mo2-eq-curve-plot{position:absolute;left:0;top:0;width:100%;height:84px;overflow:visible}
.mo2-eq-curve-grid{fill:none;stroke:rgba(255,255,255,.07);stroke-width:1;vector-effect:non-scaling-stroke;stroke-dasharray:2 4}
.mo2-eq-curve-area{stroke:none}
.mo2-eq-curve-line{fill:none;stroke:var(--mo2-eq-curve-accent);stroke-width:2;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke;filter:drop-shadow(0 0 5px rgba(95,227,201,.5))}
.mo2-eq-curve-spark{fill:#fff;filter:drop-shadow(0 0 6px rgba(255,255,255,.9))}
.mo2-eq-curve-bands{position:absolute;inset:0;display:flex}
.mo2-eq-curve-band{position:relative;flex:1 1 0}
.mo2-eq-curve-rail{position:absolute;left:50%;top:6px;width:2px;height:72px;margin-left:-1px;border-radius:2px;background:linear-gradient(180deg,rgba(255,255,255,.14),rgba(255,255,255,.03))}
.mo2-eq-curve-knob{position:absolute;left:50%;top:0;width:26px;height:14px;margin:-7px 0 0 -13px;border-radius:5px;background:linear-gradient(180deg,#3d4a63,#1a2130);border:1px solid rgba(255,255,255,.17);box-shadow:0 4px 9px -4px #000,inset 0 1px 0 rgba(255,255,255,.2);cursor:grab;touch-action:none;transform:translate3d(0,42px,0);transition:box-shadow .18s ease,border-color .18s ease}
.mo2-eq-curve-knob::after{content:"";position:absolute;left:5px;right:5px;top:50%;height:2px;margin-top:-1px;border-radius:1px;background:var(--mo2-eq-curve-accent);opacity:.8;box-shadow:0 0 6px rgba(95,227,201,.85)}
.mo2-eq-curve-knob:hover{border-color:rgba(255,255,255,.32)}
.mo2-eq-curve-knob:focus-visible{outline:2px solid #9fe8ff;outline-offset:3px}
.mo2-eq-curve-hot{cursor:grabbing;border-color:var(--mo2-eq-curve-accent);box-shadow:0 0 0 3px rgba(95,227,201,.14),0 6px 14px -5px #000}
.mo2-eq-curve-hz{position:absolute;left:0;right:0;bottom:0;text-align:center;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:8px;letter-spacing:.1em;color:rgba(233,238,248,.34)}
@media (prefers-reduced-motion:reduce){.mo2-eq-curve-knob{transition:none}.mo2-eq-curve-spark{display:none}}

