var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var reduced = !!(mq && mq.matches);
var knobs = Array.prototype.slice.call(root.querySelectorAll('.mo2-eq-curve-knob'));
var svg = root.querySelector('.mo2-eq-curve-plot');
var line = root.querySelector('.mo2-eq-curve-line');
var area = root.querySelector('.mo2-eq-curve-area');
var spark = root.querySelector('.mo2-eq-curve-spark');
var out = root.querySelector('.mo2-eq-curve-value');
var NS = 'http://www.w3.org/2000/svg';
var uid = 'mo2eq' + Math.random().toString(36).slice(2, 9);
var defs = document.createElementNS(NS, 'defs');
var grad = document.createElementNS(NS, 'linearGradient');
grad.setAttribute('id', uid);
grad.setAttribute('x1', '0'); grad.setAttribute('y1', '0');
grad.setAttribute('x2', '0'); grad.setAttribute('y2', '1');
var s1 = document.createElementNS(NS, 'stop');
s1.setAttribute('offset', '0'); s1.setAttribute('stop-color', '#5fe3c9'); s1.setAttribute('stop-opacity', '.38');
var s2 = document.createElementNS(NS, 'stop');
s2.setAttribute('offset', '1'); s2.setAttribute('stop-color', '#5fe3c9'); s2.setAttribute('stop-opacity', '0');
grad.appendChild(s1); grad.appendChild(s2); defs.appendChild(grad);
svg.insertBefore(defs, svg.firstChild);
area.setAttribute('fill', 'url(#' + uid + ')');

var N = knobs.length;
var names = ['60 Hz', '240 Hz', '1 kHz', '3 kHz', '8 kHz'];
var cen = [0.09, 0.28, 0.5, 0.72, 0.91];
var wid = [0.10, 0.085, 0.085, 0.085, 0.10];
var preset = [5.5, -3.5, 2, -2.5, 6];
var tgt = [], val = [], vel = [], i;
for (i = 0; i < N; i++) { tgt[i] = 0; val[i] = 0; vel[i] = 0; }
var MID = 42, PX = 2.72, RAIL = 72;

function gainAt(xn) {
  var g = 0, k;
  for (k = 0; k < N; k++) { var d = (xn - cen[k]) / wid[k]; g += val[k] * Math.exp(-d * d * 0.5); }
  return g;
}
function yAt(xn) { var y = MID - gainAt(xn) * PX; return y < 3 ? 3 : (y > 81 ? 81 : y); }

function render() {
  var d = '', k;
  for (k = 0; k <= 44; k++) {
    var xn = k / 44;
    d += (k ? 'L' : 'M') + (xn * 300).toFixed(1) + ' ' + yAt(xn).toFixed(2);
  }
  line.setAttribute('d', d);
  area.setAttribute('d', d + 'L300 84L0 84Z');
  for (k = 0; k < N; k++) {
