  if (reduced) { val[k] = v; vel[k] = 0; render(); }
}

knobs.forEach(function (el, k) {
  el.addEventListener('pointerdown', function (e) {
    if (e.button != null && e.button !== 0) return;
    e.preventDefault();
    el.focus();
    el.classList.add('mo2-eq-curve-hot');
    try { el.setPointerCapture(e.pointerId); } catch (err) {}
    var sy = e.clientY, sv = tgt[k];
    function move(ev) { set(k, sv - (ev.clientY - sy) * (24 / RAIL)); }
