      el.classList.remove('mo2-eq-curve-hot');
      el.removeEventListener('pointermove', move);
      el.removeEventListener('pointerup', up);
      el.removeEventListener('pointercancel', up);
    }
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up);
    el.addEventListener('pointercancel', up);
  });
  el.addEventListener('keydown', function (e) {
    var step = 0;
    if (e.key === 'ArrowUp' || e.key === 'ArrowRight') step = 1;
    else if (e.key === 'ArrowDown' || e.key === 'ArrowLeft') step = -1;
    else if (e.key === 'PageUp') step = 3;
    else if (e.key === 'PageDown') step = -3;
    else if (e.key === 'Home') { e.preventDefault(); set(k, 0); return; }
    else return;
    e.preventDefault();
    set(k, tgt[k] + step);
  });
  el.addEventListener('dblclick', function () { set(k, 0); });
});

var phase = 0, last = 0;
function frame(now) {
  var dt = last ? Math.min(0.05, (now - last) / 1000) : 0.016;
  last = now;
  var k;
  for (k = 0; k < N; k++) {
    vel[k] += (tgt[k] - val[k]) * 0.26;
    vel[k] *= 0.72;
    val[k] += vel[k];
  }
  phase = (phase + dt * 0.42) % 1;
  var sx = phase * 300;
  spark.setAttribute('cx', sx.toFixed(1));
  spark.setAttribute('cy', yAt(phase).toFixed(2));
  spark.setAttribute('opacity', (0.25 + 0.75 * Math.sin(phase * Math.PI)).toFixed(3));
  render();
  requestAnimationFrame(frame);
}

if (reduced) {
  for (i = 0; i < N; i++) { val[i] = tgt[i] = preset[i]; knobs[i].setAttribute('aria-valuenow', preset[i].toFixed(1)); }
  render();
  out.textContent = 'warm preset';
} else {
  requestAnimationFrame(frame);
  knobs.forEach(function (el, k) {
    setTimeout(function () { set(k, preset[k], true); }, 90 + k * 85);
  });
}

css:
.mo2-crossfader{--mo2-crossfader-a:#57d6ff;--mo2-crossfader-b:#ff8a5c;box-sizing:border-box;width:100%;max-width:320px;height:150px;padding:8px 11px 7px;border-radius:14px;background:linear-gradient(180deg,#161d29,#0c1016 70%,#0a0e14);border:1px solid rgba(255,255,255,.08);box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 14px 28px -18px #000;color:#e9eef8;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;display:flex;flex-direction:column;gap:5px;-webkit-user-select:none;user-select:none;overflow:hidden}
