.mo2-crossfader-seg{flex:1 1 0;border-radius:1px;background:rgba(255,255,255,.06)}
.mo2-crossfader-meter-a .mo2-crossfader-on{background:var(--mo2-crossfader-a);box-shadow:0 0 6px rgba(87,214,255,.6)}
.mo2-crossfader-meter-b .mo2-crossfader-on{background:var(--mo2-crossfader-b);box-shadow:0 0 6px rgba(255,138,92,.6)}
.mo2-crossfader-hotseg{background:#ff4d6d !important;box-shadow:0 0 8px rgba(255,77,109,.8) !important}
.mo2-crossfader-peak{background:#fff !important;box-shadow:0 0 8px rgba(255,255,255,.9) !important}
.mo2-crossfader-track{position:relative;height:42px;margin-top:2px;border-radius:8px;background:linear-gradient(180deg,#0b0f16,#131a25);box-shadow:inset 0 1px 3px rgba(0,0,0,.7),inset 0 0 0 1px rgba(255,255,255,.05)}
