.mo2-crossfader-foot{display:flex;align-items:center;justify-content:space-between;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:rgba(233,238,248,.32)}
.mo2-crossfader-curve{-webkit-appearance:none;appearance:none;font:inherit;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:rgba(233,238,248,.62);background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:999px;padding:2px 8px;cursor:pointer;transition:transform .22s cubic-bezier(.34,1.56,.64,1),background .2s ease,color .2s ease}
