var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var reduced = !!(mq && mq.matches);
var track = root.querySelector('.mo2-crossfader-track');
var cap = root.querySelector('.mo2-crossfader-cap');
var mix = root.querySelector('.mo2-crossfader-mix');
var tagA = root.querySelector('.mo2-crossfader-tag-a');
var tagB = root.querySelector('.mo2-crossfader-tag-b');
var btn = root.querySelector('.mo2-crossfader-curve');
var rowA = root.querySelector('.mo2-crossfader-meter-a .mo2-crossfader-segs');
var rowB = root.querySelector('.mo2-crossfader-meter-b .mo2-crossfader-segs');
var SEG = 14, segsA = [], segsB = [], i, s;
for (i = 0; i < SEG; i++) {
  s = document.createElement('i'); s.className = 'mo2-crossfader-seg'; rowA.appendChild(s); segsA.push(s);
  s = document.createElement('i'); s.className = 'mo2-crossfader-seg'; rowB.appendChild(s); segsB.push(s);
}

var pos = 0.5, vel = 0, glide = -1, dragging = false, sharp = false;
var span = 240;
function measure() { span = Math.max(20, track.clientWidth - cap.offsetWidth); }
measure();
if (!track.clientWidth) requestAnimationFrame(measure);
window.addEventListener('resize', measure);

function gains(p) {
  if (sharp) {
    var a = (0.5 - p) * 11 + 0.5, b = (p - 0.5) * 11 + 0.5;
    return [a < 0 ? 0 : (a > 1 ? 1 : a), b < 0 ? 0 : (b > 1 ? 1 : b)];
  }
  return [Math.cos(p * Math.PI / 2), Math.sin(p * Math.PI / 2)];
}
function label(p) {
  if (p < 0.02) return 'full A';
  if (p > 0.98) return 'full B';
  if (Math.abs(p - 0.5) < 0.02) return 'centre';
  return Math.round((1 - p) * 100) + ' A, ' + Math.round(p * 100) + ' B';
}
function aria() {
  cap.setAttribute('aria-valuenow', Math.round(pos * 100));
  cap.setAttribute('aria-valuetext', label(pos));
}

cap.addEventListener('pointerdown', function (e) {
  if (e.button != null && e.button !== 0) return;
  e.preventDefault(); cap.focus();
  dragging = true; glide = -1; vel = 0;
  measure();
  cap.classList.add('mo2-crossfader-dragging');
  try { cap.setPointerCapture(e.pointerId); } catch (err) {}
  var sx = e.clientX, sp = pos, lastX = e.clientX, lastT = performance.now();
  function move(ev) {
    var now = performance.now(), dt = Math.max(8, now - lastT);
    pos = sp + (ev.clientX - sx) / span;
    pos = pos < 0 ? 0 : (pos > 1 ? 1 : pos);
    vel = ((ev.clientX - lastX) / span) / (dt / 1000);
    lastX = ev.clientX; lastT = now;
    aria();
  }
  function up() {
    dragging = false;
    cap.classList.remove('mo2-crossfader-dragging');
    if (performance.now() - lastT > 110) vel = 0;
    vel = vel < -6 ? -6 : (vel > 6 ? 6 : vel);
    cap.removeEventListener('pointermove', move);
    cap.removeEventListener('pointerup', up);
    cap.removeEventListener('pointercancel', up);
  }
  cap.addEventListener('pointermove', move);
  cap.addEventListener('pointerup', up);
  cap.addEventListener('pointercancel', up);
});
cap.addEventListener('dblclick', function () { vel = 0; glide = 0.5; });
cap.addEventListener('keydown', function (e) {
  var d = 0;
  if (e.key === 'ArrowRight' || e.key === 'ArrowUp') d = 0.05;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') d = -0.05;
  else if (e.key === 'Home') { e.preventDefault(); glide = 0.5; vel = 0; return; }
  else if (e.key === 'End') { e.preventDefault(); glide = 1; vel = 0; return; }
  else return;
  e.preventDefault(); vel = 0; glide = -1;
  pos = Math.max(0, Math.min(1, pos + d));
  aria();
});
btn.addEventListener('click', function () {
  sharp = !sharp;
  btn.setAttribute('aria-pressed', sharp ? 'true' : 'false');
  btn.textContent = sharp ? 'curve: sharp cut' : 'curve: smooth';
});

var lvA = 0, lvB = 0, pkA = 0, pkB = 0, litA = -1, litB = -1, pA = -1, pB = -1, last = 0, t0 = performance.now();
function paint(segs, lit, peak, prevLit, prevPeak) {
  var k;
  if (lit !== prevLit || peak !== prevPeak) {
    for (k = 0; k < SEG; k++) {
      var el = segs[k], on = k < lit, hot = on && k >= SEG - 2;
