    }
  }
}
function src(t, bpm, off) {
  var p = (t * bpm / 60 + off) % 1;
  var kick = Math.exp(-p * 7);
  var snare = p > 0.5 ? Math.exp(-(p - 0.5) * 12) * 0.8 : 0;
  var hat = 0.14 * (0.5 + 0.5 * Math.sin(t * bpm * 0.42));
  var v = 0.26 + 0.6 * kick + 0.4 * snare + hat;
  return v > 1 ? 1 : v;
}
function frame(now) {
  var dt = last ? Math.min(0.05, (now - last) / 1000) : 0.016;
  last = now;
  if (!dragging) {
    if (glide >= 0) {
      pos += (glide - pos) * 0.16;
      if (Math.abs(glide - pos) < 0.002) { pos = glide; glide = -1; }
      aria();
    } else if (vel !== 0) {
      pos += vel * dt;
      vel *= Math.pow(0.12, dt);
      if (pos < 0) { pos = 0; vel = -vel * 0.32; }
      if (pos > 1) { pos = 1; vel = -vel * 0.32; }
      if (Math.abs(vel) < 0.02) vel = 0;
      aria();
    }
  }
  cap.style.transform = 'translate3d(' + (pos * span).toFixed(2) + 'px,0,0)';
  var g = gains(pos);
  mix.textContent = Math.round(g[0] * 100) + ' · ' + Math.round(g[1] * 100);
  tagA.style.color = 'rgba(233,238,248,' + (0.3 + 0.7 * g[0]).toFixed(2) + ')';
  tagB.style.color = 'rgba(233,238,248,' + (0.3 + 0.7 * g[1]).toFixed(2) + ')';
  tagA.style.transform = 'scale(' + (0.94 + 0.1 * g[0]).toFixed(3) + ')';
  tagB.style.transform = 'scale(' + (0.94 + 0.1 * g[1]).toFixed(3) + ')';
  var t = (now - t0) / 1000;
  var a = src(t, 124, 0) * g[0], b = src(t, 126, 0.37) * g[1];
  lvA = a > lvA ? a : lvA + (a - lvA) * 0.14;
  lvB = b > lvB ? b : lvB + (b - lvB) * 0.14;
  pkA = lvA > pkA ? lvA : Math.max(0, pkA - dt * 0.32);
  pkB = lvB > pkB ? lvB : Math.max(0, pkB - dt * 0.32);
  var nA = Math.round(lvA * SEG), nB = Math.round(lvB * SEG);
  var qA = pkA > 0.02 ? Math.min(SEG - 1, Math.round(pkA * SEG) - 1) : -1;
  var qB = pkB > 0.02 ? Math.min(SEG - 1, Math.round(pkB * SEG) - 1) : -1;
  paint(segsA, nA, qA, litA, pA); paint(segsB, nB, qB, litB, pB);
  litA = nA; litB = nB; pA = qA; pB = qB;
  requestAnimationFrame(frame);
}

if (reduced) {
  cap.style.transform = 'translate3d(' + (pos * span).toFixed(2) + 'px,0,0)';
  paint(segsA, 9, 11, -1, -1); paint(segsB, 8, 10, -1, -1);
  mix.textContent = '71 · 71';
} else {
  requestAnimationFrame(frame);
  glide = 0.5; pos = 0.06;
  setTimeout(function () { glide = 0.5; }, 40);
}

