var count = root.querySelector('.mo2-tap-tempo-count');
var lock = root.querySelector('.mo2-tap-tempo-lock');
var conf = root.querySelector('.mo2-tap-tempo-conffill');
var reset = root.querySelector('.mo2-tap-tempo-reset');

var taps = [], bpm = 120, shown = 120, phase = 0, punch = 0, rings = 0;

function analyse() {
  var iv = [], i;
  for (i = 1; i < taps.length; i++) iv.push(taps[i] - taps[i - 1]);
  if (!iv.length) { conf.style.transform = 'scaleX(0)'; lock.textContent = '—'; return; }
  var use = iv.slice(-5), sum = 0, k;
  for (k = 0; k < use.length; k++) sum += use[k];
  var avg = sum / use.length;
  var kept = [], ks = 0;
  for (k = 0; k < use.length; k++) if (Math.abs(use[k] - avg) < avg * 0.42) { kept.push(use[k]); ks += use[k]; }
  if (kept.length) avg = ks / kept.length;
  var v = 60000 / avg;
  bpm = v < 40 ? 40 : (v > 240 ? 240 : v);
  var dev = 0;
  for (k = 0; k < kept.length; k++) dev += Math.abs(kept[k] - avg);
  dev = kept.length ? dev / kept.length / avg : 1;
  var c = 1 - dev * 3.2;
  c = c < 0 ? 0 : (c > 1 ? 1 : c);
  conf.style.transform = 'scaleX(' + c.toFixed(3) + ')';
  lock.textContent = taps.length < 3 ? 'rough' : (c > 0.8 ? 'tight' : (c > 0.5 ? 'ok' : 'loose'));
}

function ripple() {
  if (reduced || rings > 4) return;
  var r = document.createElement('span');
  r.className = 'mo2-tap-tempo-ring';
  rings++;
  r.addEventListener('animationend', function () { rings--; if (r.parentNode) r.parentNode.removeChild(r); });
  pad.appendChild(r);
}

function tap() {
  var now = performance.now();
  if (taps.length && now - taps[taps.length - 1] > 2200) taps = [];
  taps.push(now);
  if (taps.length > 8) taps.shift();
