  count.textContent = '0'; lock.textContent = '—';
  conf.style.transform = 'scaleX(0)';
  if (reduced) { shown = 120; out.textContent = '120.0'; }
});

var last = 0;
function frame(now) {
  var dt = last ? Math.min(0.05, (now - last) / 1000) : 0.016;
