.mo2-loop-transport-time{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:17px;font-variant-numeric:tabular-nums;color:#fff}
.mo2-loop-transport-len{font-size:8px;letter-spacing:.12em;text-transform:uppercase;color:rgba(233,238,248,.32);margin-left:auto}
.mo2-loop-transport-loop{-webkit-appearance:none;appearance:none;font:inherit;font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:rgba(233,238,248,.5);background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:999px;padding:3px 8px;cursor:pointer;transition:transform .22s cubic-bezier(.34,1.56,.64,1),background .2s,color .2s}
.mo2-loop-transport-loop[aria-pressed="true"]{background:rgba(255,209,102,.16);border-color:rgba(255,209,102,.45);color:var(--mo2-loop-transport-accent)}
.mo2-loop-transport-loop:active{transform:scale(.93)}
.mo2-loop-transport-loop:focus-visible{outline:2px solid #9fe8ff;outline-offset:2px}
.mo2-loop-transport-lane{position:relative;height:64px;border-radius:8px;background:rgba(255,255,255,.03);box-shadow:inset 0 0 0 1px rgba(255,255,255,.05);overflow:hidden;cursor:crosshair;touch-action:none}
.mo2-loop-transport-region{position:absolute;left:0;top:0;bottom:0;width:100%;transform-origin:left center;background:rgba(255,209,102,.11);border-left:1px solid rgba(255,209,102,.55);pointer-events:none}
.mo2-loop-transport-flash{animation:mo2-loop-transport-blink .42s ease-out}
@keyframes mo2-loop-transport-blink{0%{background:rgba(255,209,102,.5)}100%{background:rgba(255,209,102,.11)}}
.mo2-loop-transport-wave{position:absolute;inset:0;display:flex;align-items:center;gap:1px;padding:0 2px}
.mo2-loop-transport-bar{flex:1 1 0;height:100%;border-radius:1px;background:var(--mo2-loop-transport-wave);transform:scaleY(.2)}
.mo2-loop-transport-barIn{background:#9fb4d6}
.mo2-loop-transport-handle{position:absolute;top:0;bottom:0;width:11px;margin-left:-5px;cursor:ew-resize;touch-action:none;z-index:3;background:linear-gradient(180deg,rgba(255,209,102,.9),rgba(255,209,102,.5));border-radius:3px;box-shadow:0 0 10px rgba(255,209,102,.45)}
.mo2-loop-transport-handle::after{content:"";position:absolute;left:4px;top:50%;width:3px;height:14px;margin-top:-7px;border-radius:2px;background:rgba(10,14,20,.6)}
.mo2-loop-transport-handle:focus-visible{outline:2px solid #9fe8ff;outline-offset:1px}
.mo2-loop-transport-play-head{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:#fff;box-shadow:0 0 12px rgba(255,255,255,.85);z-index:4;pointer-events:none}
.mo2-loop-transport-play-head::before{content:"";position:absolute;left:-3px;top:-4px;width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 10px rgba(255,255,255,.9)}
.mo2-loop-transport-foot{display:flex;justify-content:space-between;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,209,102,.6)}
@media (prefers-reduced-motion:reduce){.mo2-loop-transport-flash{animation:none}}

js:
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var reduced = !!(mq && mq.matches);
var lane = root.querySelector('.mo2-loop-transport-lane');
var waveEl = root.querySelector('.mo2-loop-transport-wave');
var region = root.querySelector('.mo2-loop-transport-region');
var hIn = root.querySelector('.mo2-loop-transport-in');
var hOut = root.querySelector('.mo2-loop-transport-out');
var head = root.querySelector('.mo2-loop-transport-play-head');
var timeEl = root.querySelector('.mo2-loop-transport-time');
var playBtn = root.querySelector('.mo2-loop-transport-play');
var loopBtn = root.querySelector('.mo2-loop-transport-loop');
var aEl = root.querySelector('.mo2-loop-transport-a');
var bEl = root.querySelector('.mo2-loop-transport-b');

var N = 54, bars = [], amp = [], inR = [], i;
for (i = 0; i < N; i++) {
  var x = i / N;
  var v = 0.16 + 0.42 * Math.abs(Math.sin(x * 11.4 + Math.sin(x * 5.1) * 2.2));
  v += 0.3 * Math.pow(Math.abs(Math.sin(x * 26.7)), 3);
  v += (i % 4 === 0 ? 0.16 : 0);
  amp.push(Math.min(0.98, v));
  var b = document.createElement('i');
  b.className = 'mo2-loop-transport-bar';
  waveEl.appendChild(b); bars.push(b); inR.push(false);
}

var DUR = 8, t = 0, playing = true, looping = true, lin = 0.18, lout = 0.72, W = 276, dragging = null;
function measure() { W = Math.max(40, lane.clientWidth); }
measure();
if (!lane.clientWidth) requestAnimationFrame(measure);
window.addEventListener('resize', measure);

function fmt(s) {
  var m = Math.floor(s / 60), r = s - m * 60;
  return m + ':' + (r < 10 ? '0' : '') + r.toFixed(1);
}
function syncLoop() {
  region.style.transform = 'translate3d(' + (lin * W).toFixed(1) + 'px,0,0) scaleX(' + (lout - lin).toFixed(4) + ')';
  hIn.style.transform = 'translate3d(' + (lin * W).toFixed(1) + 'px,0,0)';
  hOut.style.transform = 'translate3d(' + (lout * W).toFixed(1) + 'px,0,0)';
  hIn.setAttribute('aria-valuenow', Math.round(lin * 100));
  hOut.setAttribute('aria-valuenow', Math.round(lout * 100));
  hIn.setAttribute('aria-valuetext', fmt(lin * DUR) + ' seconds');
  hOut.setAttribute('aria-valuetext', fmt(lout * DUR) + ' seconds');
  aEl.textContent = 'in ' + (lin * DUR).toFixed(2) + 's';
  bEl.textContent = 'out ' + (lout * DUR).toFixed(2) + 's';
  for (var k = 0; k < N; k++) {
    var c = (k + 0.5) / N, on = c >= lin && c <= lout;
    if (on !== inR[k]) {
      if (on) bars[k].classList.add('mo2-loop-transport-barIn');
      else bars[k].classList.remove('mo2-loop-transport-barIn');
      inR[k] = on;
    }
  }
}

function fracFrom(e) {
  var r = lane.getBoundingClientRect();
  var f = (e.clientX - r.left) / r.width;
  return f < 0 ? 0 : (f > 1 ? 1 : f);
}
function bindHandle(el, which) {
  el.addEventListener('pointerdown', function (e) {
    if (e.button != null && e.button !== 0) return;
    e.preventDefault(); e.stopPropagation(); el.focus();
    measure();
    try { el.setPointerCapture(e.pointerId); } catch (err) {}
    function move(ev) {
      var f = fracFrom(ev);
      if (which === 0) lin = Math.min(f, lout - 0.06);
      else lout = Math.max(f, lin + 0.06);
      if (lin < 0) lin = 0; if (lout > 1) lout = 1;
      syncLoop();
    }
    function up() {
      el.removeEventListener('pointermove', move);
      el.removeEventListener('pointerup', up);
      el.removeEventListener('pointercancel', up);
    }
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up);
    el.addEventListener('pointercancel', up);
  });
  el.addEventListener('keydown', function (e) {
    var d = 0;
    if (e.key === 'ArrowRight') d = 0.02;
    else if (e.key === 'ArrowLeft') d = -0.02;
    else if (e.key === 'PageUp') d = 0.08;
    else if (e.key === 'PageDown') d = -0.08;
    else return;
    e.preventDefault();
    if (which === 0) lin = Math.max(0, Math.min(lin + d, lout - 0.06));
    else lout = Math.min(1, Math.max(lout + d, lin + 0.06));
    syncLoop();
  });
}
bindHandle(hIn, 0); bindHandle(hOut, 1);

lane.addEventListener('pointerdown', function (e) {
  if (e.button != null && e.button !== 0) return;
  t = fracFrom(e) * DUR;
  if (reduced) paint();
});
playBtn.addEventListener('click', function () {
  playing = !playing;
  playBtn.setAttribute('aria-pressed', playing ? 'true' : 'false');
  playBtn.setAttribute('aria-label', playing ? 'Pause' : 'Play');
});
loopBtn.addEventListener('click', function () {
  looping = !looping;
  loopBtn.setAttribute('aria-pressed', looping ? 'true' : 'false');
  region.style.opacity = looping ? '1' : '.35';
});

function flash() {
  if (reduced) return;
  region.classList.remove('mo2-loop-transport-flash');
  void region.offsetWidth;
  region.classList.add('mo2-loop-transport-flash');
}

function paint() {
  var f = t / DUR;
  head.style.transform = 'translate3d(' + (f * W).toFixed(1) + 'px,0,0)';
  timeEl.textContent = fmt(t);
  for (var k = 0; k < N; k++) {
    var c = (k + 0.5) / N;
    var d = Math.abs(c - f) * N;
    var boost = d < 4 ? Math.exp(-d * d * 0.34) : 0;
    bars[k].style.transform = 'scaleY(' + (amp[k] * (1 + boost * 0.75) + boost * 0.14).toFixed(4) + ')';
  }
}

var last = 0;
function frame(now) {
  var dt = last ? Math.min(0.05, (now - last) / 1000) : 0.016;
  last = now;
  if (playing) {
    t += dt;
    if (looping) {
      if (t >= lout * DUR) { t = lin * DUR; flash(); }
    }
    if (t >= DUR) { t = 0; }
  }
  paint();
  requestAnimationFrame(frame);
}

syncLoop();
if (reduced) {
  t = lin * DUR + 0.9;
  playing = false;
  playBtn.setAttribute('aria-pressed', 'false');
  playBtn.setAttribute('aria-label', 'Play');
  paint();
} else {
  t = lin * DUR;
  requestAnimationFrame(frame);
}
